!function(){const n=document.querySelector("[data-competition-list]");if(!n)return;const t=(n="")=>String(n).replace(/[&<>"']/g,n=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[n])),i=(n,i,e="btn btn-outline btn-sm")=>n?`<a class="${e}" href="${t(n)}" target="_blank" rel="noopener noreferrer">${t(i)}</a>`:"",e=n=>{const e=n.official_url||n.url||"",a=n.cover||n.image||"/img/education/makerspace-commons.webp",r=n.image_type||"相关方向图片",o="相关方向图片"===r?"相关方向图片，赛事信息以官方页面为准":`${r}，具体信息以官方页面为准`;return`<article class="competition-card">\n      <a class="competition-card-media" href="${t(e)}" target="_blank" rel="noopener noreferrer" aria-label="打开${t(n.title)}核验入口">\n        <img src="${t(a)}" alt="${t(n.image_alt||`${n.category||""}方向图片`)}" loading="lazy">\n        <span>${t(n.category||"竞赛方向")}</span>\n        <b>${t(r)}</b>\n      </a>\n      <div class="competition-card-body">\n        <h3>${t(n.title)}</h3>\n        <p class="competition-card-caption">${t(o)}</p>\n        <dl>\n          <div><dt>适合项目</dt><dd>${t(n.fit||"请结合课程顾问建议确定")}</dd></div>\n          <div><dt>组织单位</dt><dd>${t(n.organizer||"以官方通知为准")}</dd></div>\n          <div><dt>信息说明</dt><dd>${t(n.competition_status||n.status||"相关方向信息")}</dd></div>\n        </dl>\n        <div class="competition-card-foot">\n          <small>${t(n.source_label||n.source||"官方信息入口")} · 信息更新时间 ${t(n.verified_at||n.verified||"以页面显示为准")}</small>\n          <div class="competition-card-actions">\n            ${i(e,"查看官方入口")}\n            ${i(n.notice_url,"官方通知")}\n            ${i(n.registration_url,"报名入口","btn btn-primary btn-sm")}\n          </div>\n        </div>\n      </div>\n    </article>`};n.innerHTML='<div class="competition-loading" role="status">正在读取官方入口目录…</div>',fetch("/api/competitions").then(n=>{if(!n.ok)throw new Error("竞赛入口暂时无法读取");return n.json()}).then(t=>{n.innerHTML=t.length?t.map(e).join(""):'<div class="empty-panel">暂无进行中的竞赛入口，新赛季开放后会在这里公布。</div>'}).catch(()=>{const t=Array.isArray(window.QIYUAN_COMPETITIONS)?window.QIYUAN_COMPETITIONS:[];n.innerHTML=t.length?t.map(e).join(""):'<div class="empty-panel">竞赛入口暂时无法读取，请稍后刷新；规则与报名信息请以主办方官网为准。</div>'})}();
